  if d.id is null or d.state<>'published' or d.draft is distinct from (select snapshot from public.cms_versions where document_id=d.id and version_number=d.published_version) then raise exception 'Presentation import requires unchanged published source';end if;
  if d.draft->'data' ? 'presentation' then continue;end if;
  p:=jsonb_set(d.draft,'{data,presentation}',item->'presentation');
  select coalesce(max(version_number),0)+1 into next_v from public.cms_versions where document_id=d.id;
  insert into public.cms_versions(document_id,version_number,schema_version,snapshot,origin) values(d.id,next_v,d.schema_version,p,'import');
  update public.cms_documents set draft=p,published_version=next_v,revision=revision+1 where id=d.id;
  insert into public.cms_audit_logs(actor_kind,action,entity_type,entity_id,metadata) values('migration','IMPORT','institutions',d.id,'{"source":"approved-contextual-presentation","nonDestructive":true}');
 end loop;
end;$$;
